import{A as e,d as t,g as n,l as r,n as i}from"./ui-B8esxZ_K.js";import{n as a}from"./stats-BLPTDKM5.js";import{l as o}from"./kriging-D1JnBByW.js";import{t as s}from"./spatial_stats-CmM9J1Wi.js";import"./spatialData-DJcsjPX9.js";import{t as c}from"./integration_validation-CZNUXjKu.js";import{t as l}from"./bloom_validation-DhAiSrCO.js";var u=n(),d=({children:e})=>(0,u.jsx)(`pre`,{className:`my-2 overflow-x-auto rounded-lg bg-white/5 p-3 text-xs leading-relaxed text-ink`,children:e});function f(){let n=e.meta,f=e.spatial_validation;return(0,u.jsxs)(`div`,{className:`max-w-5xl`,children:[(0,u.jsx)(t,{title:`Methodology & Assumptions`,subtitle:`What this prototype does, how, and where it should not be trusted.`}),(0,u.jsxs)(r,{tone:`danger`,title:`Simulated data.`,children:[`Every observation, station value, coefficient and score in this application comes from a synthetic data generator (`,(0,u.jsx)(`code`,{children:`scripts/generate_data.py`}),`). Nothing here is a measurement of the real Great Lakes, and the models describe the simulation, not nature. Station names are descriptive labels for plausible locations, not real monitoring sites.`]}),(0,u.jsxs)(`div`,{className:`mt-4 space-y-4`,children:[(0,u.jsxs)(i,{title:`1. Data`,children:[(0,u.jsxs)(`p`,{className:`text-sm leading-relaxed text-slate-700`,children:[n.n_observations.toLocaleString(),` observations at 31 simulated monitoring stations across the five lakes, sampled every 14 days from 2018 to 2025, plus 12 unmonitored prediction locations whose own simulated data were withheld from the models (used only to check the spatial method). Variables follow the specification: total phosphorus, chlorophyll-a, water temperature, turbidity, dissolved oxygen, rainfall, season and a binary bloom flag.`]}),(0,u.jsx)(`p`,{className:`mt-2 text-sm leading-relaxed text-slate-700`,children:`Relationships were built into the generator rather than drawn independently: bloom probability rises with log phosphorus, with warmer water, with a mid-to-late-summer seasonal peak, and with a bloom the sample before (persistence). Rainfall raises risk through runoff at moderate amounts and lowers it at very heavy amounts (dilution), so the effect is not monotonic. Chlorophyll-a depends on phosphorus and jumps when a bloom is present. Noise, unobserved station effects and shared lake-level shocks keep the relationship from being deterministic. Some stations have simulated outages in 2024 and 2025 so that stale-data rules can fire, and about 2% of samples are missing at random.`})]}),(0,u.jsxs)(i,{title:`2. Models`,children:[(0,u.jsxs)(`p`,{className:`text-sm text-slate-700`,children:[(0,u.jsx)(`strong`,{children:`Logistic regression`}),` (interpretable baseline):`]}),(0,u.jsx)(d,{children:`P(B=1 | X) = 1 / (1 + e^(-z))
z = β0 + β1·ln(TP) + β2·ln(Chl) + β3·Temp + β4·Rain + β4b·Rain² + β5·DO + β6·Spring + β7·Summer + β8·Autumn`}),(0,u.jsx)(`p`,{className:`text-sm text-slate-700`,children:`Inputs are standardised, season is dummy-coded against Winter, and the fit uses L2 regularisation (C = 1) by scikit-learn on the 2018-2023 training period. The spec lists a single rainfall coefficient; a squared term was added so rainfall can have a non-monotonic effect. Coefficients are in the Model Performance page and are exported to JSON, then evaluated in the browser. They are fitted values, not hand-set.`}),(0,u.jsxs)(`p`,{className:`mt-3 text-sm text-slate-700`,children:[(0,u.jsx)(`strong`,{children:`Random forest`}),` (nonlinear): 60 trees, depth at most 6, at least 15 samples per leaf. The exported trees are walked in the browser, so the in-app probabilities are the model's, and a parity check (`,(0,u.jsx)(`code`,{children:`npm run verify`}),`) confirms the JavaScript matches scikit-learn on 40 test vectors.`]}),(0,u.jsxs)(`p`,{className:`mt-3 text-sm text-slate-700`,children:[(0,u.jsx)(`strong`,{children:`Target leakage and the two configurations.`}),` The target is "bloom observed at this sample". Chlorophyll-a at the same sample is partly a consequence of the bloom, so a model using it (`,(0,u.jsx)(`em`,{children:`nowcast`}),`) scores AUC about `,a(e.metrics.nowcast.holdout.lr.auc,2),` and is not a forecast. The `,(0,u.jsx)(`em`,{children:`early-warning`}),` configuration uses only the previous sample's values (14 to 42 days earlier) plus the season of the predicted date, and scores about `,a(e.metrics.early.holdout.lr.auc,2),`. All risk classification, maps and alerts use the early-warning configuration.`]}),(0,u.jsxs)(`p`,{className:`mt-3 text-sm text-slate-700`,children:[(0,u.jsx)(`strong`,{children:`Validation.`}),` Chronological holdout (train to 2023, test 2024-2025) and five-fold station-aware cross-validation, shown beside random-fold cross-validation to expose optimism. Neither model is declared better unless the numbers separate; on this data they are close.`]})]}),(0,u.jsxs)(i,{title:`3. Spatial estimation for unmonitored locations`,children:[(0,u.jsx)(d,{children:`Ẑ(x) = Σ wᵢ Zᵢ / Σ wᵢ,    wᵢ = 1 / (dᵢ + ε)^p,    ε = 1 km,  p = 2 (editable)`}),(0,u.jsxs)(`p`,{className:`text-sm leading-relaxed text-slate-700`,children:[`Distances are great-circle (haversine). Only stations on the `,(0,u.jsx)(`em`,{children:`same lake`}),` within the search radius (default 150 km), at most k = 4, and with an observation in the last 45 days contribute, so nothing is blended across lakes. Phosphorus, chlorophyll-a and oxygen use a recency-weighted mean of the last three samples; temperature and rainfall use the latest. The estimated inputs go through the early-warning models.`]}),(0,u.jsxs)(`p`,{className:`mt-2 text-sm leading-relaxed text-slate-700`,children:[`A location is flagged as `,(0,u.jsx)(`em`,{children:`interpolation`}),` when it falls inside the convex hull of at least three contributing stations, otherwise `,(0,u.jsx)(`em`,{children:`extrapolation`}),`. Confidence is a heuristic index combining nearest distance, station count, agreement among stations, interpolation versus extrapolation and model agreement. It is not a statistical confidence interval. The risk layer on the map is a grid clipped to the lake outlines and left blank beyond the search radius.`]}),(0,u.jsxs)(`p`,{className:`mt-2 text-sm leading-relaxed text-slate-700`,children:[`Leave-one-station-out check (`,f.n_cases.toLocaleString(),` cases, 2024-2025): phosphorus R² `,a(f.tp.r2_idw,2),` and RMSE `,a(f.tp.rmse_idw,1),` µg/L; bloom-ranking AUC `,a(f.bloom_auc.spatial_idw,3),` versus `,a(f.bloom_auc.own_station_inputs,3),` with the station's own inputs. This supports the method for stations with same-lake neighbours in the simulation. It does not validate it for real lakes, where nutrient plumes and bays vary sharply over short distances.`]})]}),(0,u.jsxs)(i,{title:`3b. Spatial analytical framework: Kriging, spatial autocorrelation and AHP`,children:[(0,u.jsxs)(`p`,{className:`text-sm leading-relaxed text-slate-700`,children:[`Three methods form the core framework. They answer different questions and are kept apart: `,(0,u.jsx)(`strong`,{children:`Kriging`}),` estimates concentrations where nobody sampled, `,(0,u.jsx)(`strong`,{children:`Moran's I and the semivariogram`}),` test whether that spatial structure exists, and `,(0,u.jsx)(`strong`,{children:`AHP`}),` turns indicators into a relative risk score. The `,(0,u.jsx)(`strong`,{children:`bloom model`}),` (section 2) stays a separate, validated probability model.`]}),(0,u.jsxs)(`p`,{className:`mt-3 text-sm text-slate-700`,children:[(0,u.jsx)(`strong`,{children:`Ordinary Kriging.`}),` For stations 1…n on the same lake the estimate at a new point is Σλᵢzᵢ, with weights from the system below (γ is the fitted semivariogram, μ a Lagrange multiplier that makes the weights sum to 1):`]}),(0,u.jsx)(d,{children:`[ γ(dᵢⱼ)  1 ] [ λ ]   [ γ(d₀ᵢ) ]
[   1ᵀ    0 ] [ μ ] = [    1    ]       kriging variance = Σλᵢγ(d₀ᵢ) + μ,   standard error = √variance`}),(0,u.jsxs)(`p`,{className:`text-sm leading-relaxed text-slate-700`,children:[`Distances are great-circle. Kriging is done lake by lake, so values are never interpolated across lakes or land. TP, chlorophyll-a, nitrate and turbidity are kriged on the log scale (the shown estimate is the median, and intervals are asymmetric); temperature and oxygen on the raw scale. Spherical, exponential and Gaussian variograms are fitted by weighted least squares to a pooled within-lake experimental semivariogram of 2018-2023 (lag `,s.meta.lag_km,` km, cut-off `,s.meta.cutoff_km,` km) and compared by leave-one-station-out cross-validation on `,o.meta.n_cases.toLocaleString(),` station-dates in 2024-2025, never on the fitting period. The app recomputes Kriging in the browser with the same equations; a parity test checks it against PyKrige.`]}),(0,u.jsx)(`p`,{className:`mt-2 text-sm leading-relaxed text-slate-700`,children:`Cross-validation result: the best Kriging variogram is between 1% worse and 7% better than inverse-distance weighting in RMSE and the lake mean by up to 20%, because each lake has just 6-7 stations. Its practical advantage is calibrated uncertainty (RMSSE near 1, 95% coverage 87-96% for the best models). The Gaussian model is unstable on TP (RMSSE about 3) and is flagged on the page.`}),(0,u.jsxs)(`p`,{className:`mt-3 text-sm text-slate-700`,children:[(0,u.jsx)(`strong`,{children:`Spatial autocorrelation.`}),` Global Moran's I = (n/S₀) ΣΣwᵢⱼ zᵢzⱼ / Σzᵢ² with kNN, distance-band or inverse-distance weights (same-lake restriction and row-standardisation selectable), expected value −1/(n−1), a normal-theory z-score and a permutation pseudo-p-value (two-sided, tie-safe). Local Moran's I (scaled as in PySAL) uses conditional permutations, optionally Benjamini-Hochberg adjusted, and classifies HH, LL, HL and LH clusters. Results agree with esda to numerical precision. Regional I is strong, but with 6-7 stations per lake the within-lake permutation tests have little power and few local clusters survive; the page says so. The variogram ranges reach the search limit for most indicators: the data show a within-lake gradient rather than a clean sill, so the range is not a physical correlation length. Anisotropy is not supported by so few pairs, and universal Kriging with a trend is a listed limitation.`]}),(0,u.jsxs)(`p`,{className:`mt-3 text-sm text-slate-700`,children:[(0,u.jsx)(`strong`,{children:`AHP.`}),` Users enter Saaty 1-9 pairwise judgments for TP, chlorophyll-a, nitrate, temperature, DO and turbidity. Weights are the principal eigenvector (power iteration, checked against numpy). Consistency: CI = (λmax − n)/(n − 1), CR = CI/RI with Saaty's random index (RI = 1.24 for n = 6) and a configurable threshold (default 0.10); inconsistent matrices are flagged and the judgment that disagrees most with the weights is highlighted. Each indicator is mapped to a risk contribution r from 0 to 1 (piecewise linear or logistic) between editable reference values, with DO reversed. The composite is R = 100·Σwᵢrᵢ. The judgments, reference ranges and score bands (25/50/75) are `,(0,u.jsx)(`strong`,{children:`illustrative defaults`}),`, not regulatory criteria.`]}),(0,u.jsxs)(`p`,{className:`mt-3 text-sm text-slate-700`,children:[(0,u.jsx)(`strong`,{children:`Integration and uncertainty.`}),` At each unmonitored location the six indicators are kriged, normalised and scored; the shown score uses the Kriging median. A seeded Monte Carlo (default 1,000 draws) samples each indicator from N(μ, SE²) on its analysis scale (optionally with a shared error component, correlation ρ), rescoring each draw. The 5th-95th percentiles are the risk interval and the share of draws at or above the threshold is the exceedance probability. Checked against the hidden simulated truth at the 12 unmonitored sites (`,c.meta.cases,` location-dates): AHP-score MAE `,a(c.score_error.kriging.mae,1),` points for Kriging, `,a(c.score_error.idw.mae,1),` for IDW and `,a(c.score_error.lake_mean.mae,1),` for the lake mean; the 90% interval contained the truth `,(c.interval90_coverage*100).toFixed(0),`% of the time; exceedance-probability Brier `,a(c.exceedance.brier,3),` against `,a(c.exceedance.brier_climatology,3),` for the base rate.`]}),(0,u.jsxs)(`p`,{className:`mt-3 text-sm text-slate-700`,children:[(0,u.jsx)(`strong`,{children:`Three different quantities.`}),` A kriged concentration is an estimated measurement. An AHP score is a relative ranking from judgments and is not a probability: 75/100 does not mean a 75% bloom chance. A bloom probability comes only from the logistic model (AUC `,a(l.models.lr.auc,2),`, calibration slope `,a(l.models.lr.calibration_slope,2),`, ECE `,a(l.models.lr.ece,3),` on the 2024-2025 holdout). When the bloom model is fed Kriged inputs for a hidden station its AUC is `,a(o.bloom_with_kriged_inputs.krige.auc,3),`, against `,a(o.bloom_with_kriged_inputs.own.auc,3),` with the station's own measurements.`]}),(0,u.jsx)(r,{tone:`warn`,title:`What Kriging variance does not cover.`,children:`It reflects only the spatial prediction error under the fitted variogram. It excludes variogram estimation error, change between sampling dates, non-stationarity and measurement error, so intervals are optimistic. Interpolated values are tagged ESTIMATED everywhere and are never written into the observed data.`})]}),(0,u.jsx)(i,{title:`4. Risk levels and alerts`,children:(0,u.jsx)(`p`,{className:`text-sm leading-relaxed text-slate-700`,children:`Risk level is calculated from the predicted probability using editable thresholds (default Moderate 20%, High 40%, Critical 70%). These are illustrative prototype settings, not regulatory limits or accepted scientific standards. Alert rules (critical, high, stale-data verification, field-sampling for weakly supported unmonitored areas, escalation between consecutive runs, interpolated AHP priority, poorly constrained interpolation, and disagreement between the AHP band and the bloom model) are listed in the Early-Warning Center. Alerts are model-generated candidates for human review. No page represents any of them as an issued warning.`})}),(0,u.jsx)(i,{title:`5. Known limitations`,children:(0,u.jsxs)(`ul`,{className:`list-disc space-y-1.5 pl-5 text-sm leading-relaxed text-slate-700`,children:[(0,u.jsx)(`li`,{children:`Synthetic data: results show how the system would work, not what is happening in the lakes.`}),(0,u.jsx)(`li`,{children:`Associations are conditional model estimates. The nutrient-bloom curves do not prove that cutting phosphorus would prevent blooms in a real lake.`}),(0,u.jsx)(`li`,{children:`Because phosphorus was built into the generator, its strong effect is partly circular. A real dataset could show weaker or different relationships.`}),(0,u.jsx)(`li`,{children:`Lake outlines are schematic polygons, not survey-grade boundaries, and station coordinates are illustrative.`}),(0,u.jsx)(`li`,{children:`The model predicts presence of a bloom at the next sample. It does not predict bloom size, toxin concentrations or drinking-water impact.`}),(0,u.jsx)(`li`,{children:`The spatial method ignores currents, tributary inputs and bathymetry. Isolated bays and near-shore plumes are the likeliest places for it to be wrong.`}),(0,u.jsx)(`li`,{children:`Feature importance and the "main contributing factors" are one-at-a-time probability changes; they describe the model, not causes.`}),(0,u.jsx)(`li`,{children:`Kriging uses 6-7 stations per lake, so variograms are weakly constrained, within-lake spatial tests have low power, and Kriging is only marginally better than IDW.`}),(0,u.jsx)(`li`,{children:`AHP weights, reference ranges and score bands are illustrative judgments; Monte Carlo propagates Kriging error only (not weight uncertainty, variogram error or temporal change) and its 90% interval is slightly narrow.`}),(0,u.jsx)(`li`,{children:`Not implemented: universal or regression Kriging, anisotropic variograms, space-time Kriging and drift terms.`}),(0,u.jsx)(`li`,{children:`The default analysis date, 2 September 2025, was chosen as a peak-season run that exercises every alert rule. The selector in the header re-runs everything for any other date.`})]})}),(0,u.jsx)(i,{title:`6. Reproducing and deploying`,children:(0,u.jsxs)(`p`,{className:`text-sm leading-relaxed text-slate-700`,children:[(0,u.jsx)(`code`,{children:`npm run data`}),` regenerates the dataset, runs the data checks and refits the bloom models; `,(0,u.jsx)(`code`,{children:`npm run analysis`}),` reruns variogram fitting, Moran's I, Kriging cross-validation (PyKrige) and the integration validation; `,(0,u.jsx)(`code`,{children:`npm test`}),` runs the JavaScript and Python tests. `,(0,u.jsx)(`code`,{children:`npm run dev`}),` starts the app, `,(0,u.jsx)(`code`,{children:`npm run build`}),` produces a static bundle for Vercel (`,(0,u.jsx)(`code`,{children:`vercel.json`}),` included). The app needs no API keys or network access; if basemap tiles cannot load, the schematic lake outlines remain.`]})})]})]})}export{f as default};